/*
 * ONE GATE, IN ONE PLACE (DBU-02). A page that forgot its own check would be the one somebody
 * could open, so no page checks.
 *
 *   Signed out: every page but Sign in, Not found and Unsubscribe goes to Sign in.
 *   Unsubscribe (DBU-07) is open to everyone, signed in or not: its link comes from an email.
 *   Signed in, on Sign in: on to their side (staff to Learners, a learner to Home).
 *   A learner on a coach page: Not found. Not an error, and not the coach's page.
 *   Staff on a learner page: Learners. A coach has no plan of their own.
 *
 * PUBLIC and COACH are lists of what is allowed, so a page added later is closed to the
 * signed-out by default, and open only to learners until it is listed as a coach page.
 *
 * Who is staff is the backend's role, never an address. Roles not known yet are waited for,
 * never guessed: `roles` is undefined until the backend has said (a magic link's exchange
 * carries them, a stored session is re-read on load).
 *
 * NONE OF THIS KEEPS DATA PRIVATE. Every read and write is a cloud function behind
 * nodegx.security.json; this decides what the browser draws.
 */
const PUBLIC = ['Pages/Sign in', 'Pages/Not found', 'Pages/Unsubscribe'];
const ANYONE = ['Pages/Unsubscribe'];
const COACH = ['Pages/Learners', 'Pages/Learner plan', 'Pages/Inbox', 'Pages/Plan templates', 'Pages/Homework library', 'Pages/Settings'];
const page = String(Inputs.page || '').replace(/^\/+/, '');
if (!page || ANYONE.includes(page)) return;
if (Inputs.signedIn !== true) {
  if (!PUBLIC.includes(page)) Outputs.toSignIn();
  return;
}
if (!Array.isArray(Inputs.roles)) return;
const staff = Inputs.roles.map((r) => (r && r.name) || r).includes('staff');
if (page === 'Pages/Sign in') {
  if (staff) Outputs.toLearners();
  else Outputs.toHome();
} else if (staff && !COACH.includes(page) && page !== 'Pages/Not found') {
  Outputs.toLearners();
} else if (!staff && COACH.includes(page)) {
  Outputs.toNotFound();
}

// Once per visit, as soon as it is known whether someone is signed in: the name learners see
// (Settings), into every word that names the coach. Nothing set, or no answer: the words keep
// their own "your coach". (Not on the router's page: that made Home ask before the gate had
// sent a signed-out visitor away.)
// In the demo it waits for the service worker (window.dbuDemo.ready): on a first visit that never
// settles, because the page reloads under the worker, so nothing reaches the web server instead.
if (Inputs.signedIn === undefined || window.__dbuCoachNameAsked) return;
window.__dbuCoachNameAsked = true;
const demoReady = window.dbuDemo ? window.dbuDemo.ready : Promise.resolve(true);
Promise.resolve(demoReady).then((ok) => {
  if (!ok) return null;
  return Noodl.CloudFunctions.run('coachName', {});
}).then((r) => {
  const name = String((r && r.name) || '').trim();
  if (!name) return;
  Outputs.words = { coachName: name, coachNameStart: name };
  Outputs.ready();
}).catch(() => {});
